"""Brute-force cross-check of the guarded minimum-cost preparation."""
import itertools, random, sys
sys.path.insert(0, '/workspace/project/src')
from eywa.state import StateMachine

def brute(spec, initial_index, target_index, disabled):
    transitions = spec['transitions']
    n = len(spec['states'])
    best = None
    def walk(state, cost, seq, used):
        nonlocal best
        if state == target_index:
            key = (cost, len(seq), tuple(seq))
            if best is None or key < best:
                best = key
        if len(seq) >= n + 1:
            return
        for position, t in enumerate(transitions):
            if position in disabled:
                continue
            if spec['states'].index(t['from']) != state:
                continue
            if t['to'] in used:
                continue
            walk(spec['states'].index(t['to']), cost + t['cost'],
                 seq + [t['command']], used | {t['to']})
    walk(initial_index, 0, [], {initial_index})
    return None if best is None else (best[0], list(best[2]))

random.seed(1234)
fails = 0
for trial in range(4000):
    n = random.randint(1, 6)
    states = ['S%d' % i for i in range(n)]
    transitions = []
    for _ in range(random.randint(0, 10)):
        a = random.choice(states); b = random.choice(states)
        cmd = random.choice(['a', 'b', 'c', 'ab', 'aa', 'x', '', 'zz'])
        transitions.append({'from': a, 'to': b, 'command': cmd,
                            'cost': random.randint(1, 5), 'when': None})
    spec = {'states': states, 'initial': states[0], 'state_param': 's',
            'message_param': 'm', 'transitions': transitions}
    machine = StateMachine(spec)
    total = len(transitions)
    for target in range(n):
        for size in range(0, min(total, 3) + 1):
            for disabled in itertools.combinations(range(total), size):
                got = machine.plan(target, disabled)
                want = brute(spec, 0, target, set(disabled))
                if got != want:
                    fails += 1
                    print('MISMATCH trial', trial, 'target', target,
                          'disabled', disabled, 'got', got, 'want', want)
                    print('  states', states)
                    for t in transitions: print('   ', t)
                    if fails > 5: sys.exit(1)
print('state fuzz done, failures:', fails)
PYEOF
